mapper.select:
select t.log_type logType,t.res_param resParam,t.log_cmd logCmd,t.machine_code machineCode,t.busi_key
busiKey,t.log_id logId,t.status_cd statusCd,t.req_param reqParam,t.community_id communityId
from machine_trans_log t
where 1 =1

    and t.log_type= #{logType}


    and t.res_param= #{resParam}


    and t.log_cmd= #{logCmd}


    and t.machine_code= #{machineCode}


    and t.busi_key= #{busiKey}


    and t.log_id= #{logId}


    and t.status_cd= #{statusCd}


    and t.req_param= #{reqParam}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

